float sdRoundBox( in vec2 p, in vec2 b, in vec4 r , vec2 offset) 
{
p += vec2(-0.3, 0.) + offset;
    r.xy = (p.x>0.0)?r.xy : r.zw;
    r.x  = (p.y>0.0)?r.x  : r.y;
    vec2 q = abs(p)-b+r.x;
    return min(max(q.x,q.y),0.0) + length(max(q,0.0)) - r.x;
}

float sdCircle(vec2 p, float r, vec2 offset) {
    return length(p + offset + vec2(0.2, 0.)) - r;
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 p = (2.0 * fragCoord - iResolution.xy) / iResolution.y;

    vec2 uncertaintyOffset[6]; 
    vec3 emotionalShades[6];


    vec3 col = vec3(0.1, 0.1, 0.15);

    // Colors inspired by emotions towards you since day 0:
    emotionalShades[0] = vec3(255.0 / 255.0, 191.0 / 255.0, 0.0 / 255.0); // Wow, but impossible! // Gold
    emotionalShades[1] = vec3(195.0 / 255.0, 181.0 / 255.0, 255.0 / 255.0);  // I feel intellectually connected!! // Soft lavendar
    emotionalShades[2] = vec3(163.0 / 255.0, 163.0 / 255.0, 163.0 / 255.0); // He has a lot of expectations, I feel dimmed.. // Muted Grey 
    emotionalShades[3] = vec3(200.0 / 255.0, 100.0 / 255.0, 5.0 / 255.0); // Let’s shift from fear to understanding, let’s confront! // Warm Terracota
    emotionalShades[4] = vec3(239.0 / 255.0, 168.0 / 255.0, 184.0 / 255.0); // I'm allured by his sense, voice, touches, and taste!  // Romantic Pink
    emotionalShades[5] = vec3(41.0 / 255.0, 134.0 / 255.0, 204.0 / 255.0); // Wait, isn't he the CEO yet? well.. "HE IS" // Rich Navy Blue


    // Animation: Each part of you dances infront of my eyes, as I'm trying to figure it out..
    float realizationSpeed = 0.1; // slower movement, well cuz I'm a snail..
    float emotionalTide = sin(iTime * realizationSpeed) * 0.5; // Love isn't static, it flows..
    vec2 emotionalAnchor = vec2(0.0);


    uncertaintyOffset[0] = emotionalAnchor + vec2(sin(iTime * 1.5), cos(iTime * 1.5)) * 0.2 * emotionalTide;
    uncertaintyOffset[1] = emotionalAnchor + vec2(cos(iTime * 1.2), sin(iTime * 1.2)) * 0.2 * emotionalTide;
    uncertaintyOffset[2] = emotionalAnchor + vec2(sin(iTime * 1.8), cos(iTime * 1.8)) * 0.2 * emotionalTide;
    uncertaintyOffset[3] = emotionalAnchor + vec2(cos(iTime * 2.0), sin(iTime * 2.0)) * 0.2 * emotionalTide;
    uncertaintyOffset[4] = emotionalAnchor + vec2(sin(iTime * 2.3), cos(iTime * 2.3)) * 0.2 * emotionalTide;
    uncertaintyOffset[5] = emotionalAnchor + vec2(sin(iTime * 2.6), cos(iTime * 2.6)) * 0.2 * emotionalTide;



    for (int i = 0; i < 6; i++) {

        // Under processing 
        float d = sdCircle(p, 0.5, uncertaintyOffset[i]); 
        vec2 boxSize = vec2(0.12, 0.5);  
        vec4 radius = vec4(0.1);        
        radius = min(radius, min(boxSize.x, boxSize.y));
        float b = sdRoundBox(p, boxSize, radius, uncertaintyOffset[i]);
        // End of processing

        float a = min(b, d);
        float aMask = 1.0 - smoothstep(0.0, 0.01, abs(a)); // Where one vision of you is assembled..
        col = mix(col, emotionalShades[i], aMask); // When everything comes togther, I see only You!
    }



    fragColor = vec4(col, 1.0);
}
